<?php
declare(strict_types=1);
function database(): PDO { static $db; if ($db) return $db; $path=dirname(__DIR__).'/storage/database.sqlite'; if(!is_dir(dirname($path))) mkdir(dirname($path),0775,true); $db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS admin_users (id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_login_at TEXT NULL); CREATE TABLE IF NOT EXISTS interest_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT,submission_uuid TEXT NOT NULL UNIQUE,form_id TEXT NOT NULL,schema_version INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,country TEXT NULL,payload_json TEXT NOT NULL,form_snapshot_json TEXT NOT NULL,consent INTEGER NOT NULL,ip_hash TEXT NOT NULL,user_agent_hash TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS submission_rate_limits (id INTEGER PRIMARY KEY AUTOINCREMENT,key_hash TEXT NOT NULL UNIQUE,window_started_at TEXT NOT NULL,attempt_count INTEGER NOT NULL,updated_at TEXT NOT NULL); CREATE INDEX IF NOT EXISTS idx_interest_created_at ON interest_submissions(created_at DESC); CREATE INDEX IF NOT EXISTS idx_interest_email ON interest_submissions(email);'); return $db; }
